duck-typing.pseudocode:
class Duck:
    def quack(self):
        return '꽥꽥'

class Robot:  # Duck과 상속 관계 없음
    def quack(self):
        return '삐- 꽥'

def make_sound(x):
    return x.quack()  # 타입이 아닌 메서드 보유 여부만 요구

for obj in [Duck(), Robot()]:
    print(make_sound(obj))  # 둘 다 동작
make_sound(42)  # 실행 시 AttributeError
